<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Setting;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class HomePageController extends Controller{public function edit(){return view('admin.home.edit',['values'=>Setting::where('group','homepage')->pluck('value','key')]);}public function update(Request $r){$d=$r->validate(['home_eyebrow'=>'nullable|max:255','home_title'=>'required|max:255','home_intro'=>'nullable|max:2000','home_about_title'=>'nullable|max:255','home_about_text'=>'nullable|max:5000','home_final_title'=>'nullable|max:255','home_3d_model'=>'nullable|file|max:20480','remove_3d'=>'nullable|boolean','home_3d_rot_x'=>'nullable|numeric|min:-360|max:360','home_3d_rot_y'=>'nullable|numeric|min:-360|max:360','home_3d_rot_z'=>'nullable|numeric|min:-360|max:360','home_3d_scale'=>'nullable|numeric|min:0.1|max:5','home_3d_wireframe'=>'nullable|boolean','home_3d_bloom'=>'nullable|boolean']);foreach(['home_eyebrow','home_title','home_intro','home_about_title','home_about_text','home_final_title','home_3d_rot_x','home_3d_rot_y','home_3d_rot_z','home_3d_scale'] as $key)Setting::updateOrCreate(['key'=>$key],['value'=>$d[$key]??null,'group'=>'homepage','label'=>$key]);foreach(['home_3d_wireframe','home_3d_bloom'] as $key)Setting::updateOrCreate(['key'=>$key],['value'=>$r->boolean($key)?'1':'0','group'=>'homepage','label'=>$key]);$old=Setting::valueOf('home_3d_model');if($r->boolean('remove_3d')){if($old)Storage::disk('public')->delete($old);Setting::updateOrCreate(['key'=>'home_3d_model'],['value'=>null,'group'=>'homepage','label'=>'3D-модель главной']);}elseif($r->hasFile('home_3d_model')){if($old)Storage::disk('public')->delete($old);$path=$r->file('home_3d_model')->store('home-models','public');Setting::updateOrCreate(['key'=>'home_3d_model'],['value'=>$path,'group'=>'homepage','label'=>'3D-модель главной']);}return back()->with('ok','Главная страница сохранена');}}